package com.example.leavemanagement.policy.application;
import com.example.leavemanagement.audit.persistence.*; import com.example.leavemanagement.policy.persistence.*; import com.example.leavemanagement.shared.api.DomainException; import com.example.leavemanagement.shared.security.CurrentActorProvider; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class HolidayAdministrationService { private final CompanyHolidayRepository holidays;private final AuditEventRepository audits;private final CurrentActorProvider actors; public HolidayAdministrationService(CompanyHolidayRepository h,AuditEventRepository a,CurrentActorProvider c){holidays=h;audits=a;actors=c;} private void admin(){if(!actors.require().hasRole("ADMINISTRATOR"))throw new DomainException(403,"ACCESS_DENIED","Administrator role is required");} public List<View> list(LocalDate from,LocalDate to){admin();return holidays.findAllByDateBetweenOrderByDate(from,to).stream().map(this::view).toList();} public View create(Create c){admin();if(holidays.existsByDate(c.date()))throw new DomainException(409,"RESOURCE_CONFLICT","Holiday date already exists");var h=holidays.save(CompanyHolidayEntity.create(UUID.randomUUID(),c.date(),c.name(),c.active(),Instant.now()));audits.save(AuditEventEntity.administration(actors.require().userId(),"HOLIDAY_CREATED","COMPANY_HOLIDAY",h.getId(),null,null,"{\"active\":"+h.isActive()+"}"));return view(h);} public View update(UUID id,Update c){admin();var h=holidays.findById(id).orElseThrow(()->new DomainException(404,"RESOURCE_NOT_FOUND","Holiday was not found"));if(h.getVersion()!=c.expectedVersion())throw new DomainException(409,"STALE_VERSION","The holiday was changed; reload and retry");var before="{\"active\":"+h.isActive()+"}";h.update(c.date(),c.name(),c.active(),Instant.now());audits.save(AuditEventEntity.administration(actors.require().userId(),c.active()?"HOLIDAY_UPDATED":"HOLIDAY_DEACTIVATED","COMPANY_HOLIDAY",id,null,before,"{\"active\":"+c.active()+"}"));return view(h);} private View view(CompanyHolidayEntity h){return new View(h.getId(),h.getDate(),h.getName(),h.isActive(),h.getVersion());} public record Create(LocalDate date,String name,boolean active){} public record Update(LocalDate date,String name,boolean active,long expectedVersion){} public record View(UUID id,LocalDate date,String name,boolean active,long version){} }
